insert into public.card_definitions (id, category, title, description, effects, choices) values
  ('E01', 'event', 'Year-End Bonus', 'Your boss finally remembered you still work here.', '[["cash",1000000,"bonus"]]'::jsonb, null),
  ('E02', 'event', 'Holiday Bonus Lands', 'The THR hits your account. Your balance smiles for three days.', '[["cash",1000000,"bonus"]]'::jsonb, null),
  ('E03', 'event', 'Side Project', 'A college friend needs a logo. Decent pay, infinite revisions.', '[["cash",600000]]'::jsonb, null),
  ('E04', 'event', 'Fun Run Door Prize', 'You came for the free T-shirt and went home with a fridge.', '[["cash",500000]]'::jsonb, null),
  ('E05', 'event', 'Phone Takes a Dive', 'The screen now looks like a map of shortcut alleys.', '[["pay",500000]]'::jsonb, null),
  ('E06', 'event', 'Motorbike Breaks Down', 'It stalls exactly when you’re in a hurry.', '[]'::jsonb, '[{"l":"Official workshop","fx":[["pay",400000]]},{"l":"Roadside mechanic","fx":[["pay",150000],["back",3]],"m":"It ran… for three blocks."}]'::jsonb),
  ('E07', 'event', 'Midnight Flash Sale', '50% off! Things you don’t need suddenly feel essential.', '[]'::jsonb, '[{"l":"Check out and resell","fx":[["gamble",300000,700000,50]]},{"l":"Close the app","fx":[]}]'::jsonb),
  ('E08', 'event', 'Dog-Logo Crypto Coin', 'Up 300% this week. Your friends won’t stop posting screenshots.', '[]'::jsonb, '[{"l":"FOMO in Rp500K","fx":[["gamble",500000,1400000,35]]},{"l":"Pretend you didn’t see it","fx":[]}]'::jsonb),
  ('E09', 'event', 'Instant Loan SMS', '“Funds in 5 minutes!” The interest rate is not mentioned.', '[]'::jsonb, '[{"l":"Take Rp1M now","fx":[["loan",1000000,1300000]],"m":"You must repay Rp1.3M at your next Payday."},{"l":"Block the number","fx":[]}]'::jsonb),
  ('E10', 'event', 'Going Home for Lebaran', 'Pricey tickets, endless traffic, but home is home. Advance to Payday.', '[["goto",0]]'::jsonb, null),
  ('E11', 'event', 'Concert in the Capital', 'Ticket war at noon. Your fingers are fast today.', '[]'::jsonb, '[{"l":"Buy a ticket (Rp200K) and go","fx":[["pay",200000],["goto",35]]},{"l":"Watch the livestream","fx":[]}]'::jsonb),
  ('E12', 'event', 'Promo Flight', 'A cheap ticket pops up in a friend’s story.', '[]'::jsonb, '[{"l":"Fly (Rp200K) to the Airport","fx":[["pay",200000],["goto",27]]},{"l":"Stay home","fx":[]}]'::jsonb),
  ('E13', 'event', 'Promotion!', 'The long meetings paid off. Your name came up.', '[["cash",800000,"bonus"]]'::jsonb, null),
  ('E14', 'event', 'Restructuring', 'A more polite word for layoffs. You keep your job, not your bonus.', '[["pay",1500000,"layoff"]]'::jsonb, null),
  ('E15', 'event', 'Wedding Season', 'Three invitations, one weekend. Pay Rp100K to every other player.', '[["each",100000]]'::jsonb, null),
  ('E16', 'event', 'Your Birthday', 'Social media reminded everyone. Collect Rp100K from every player.', '[["collect",100000]]'::jsonb, null),
  ('E17', 'event', 'Arisan Jackpot', 'Your name came out first at the office arisan. Collect Rp150K from every player.', '[["collect",150000]]'::jsonb, null),
  ('E18', 'event', 'Typo Transfer', 'One wrong digit and your money moved to a stranger.', '[["pay",400000]]'::jsonb, null),
  ('E19', 'event', 'Online Shopping Scam', 'You ordered sneakers. A neatly wrapped brick arrived.', '[["pay",500000]]'::jsonb, null),
  ('E20', 'event', 'Freelance Translation', '40 pages due tomorrow morning.', '[["cash",400000]]'::jsonb, null),
  ('E21', 'event', 'Viral for a Day', 'A million views of you falling off a bicycle.', '[["cash",300000]]'::jsonb, null),
  ('E22', 'event', 'Dengue Fever', 'Three days in hospital. Mosquitoes don’t discriminate.', '[["pay",1000000,"health"]]'::jsonb, null),
  ('E23', 'event', 'Shortcut Card', 'A friend shares a secret back road. Keep this card to escape the Traffic Jam once.', '[["jamcard"]]'::jsonb, null),
  ('E24', 'event', 'Daytime Headlight Ticket', 'You forgot. The officer didn’t.', '[["pay",200000]]'::jsonb, null),
  ('E25', 'event', 'Cousin’s Mega Wedding', 'Everyone is invited and everyone brings an envelope. Collect Rp200K from every player.', '[["collect",200000]]'::jsonb, null),
  ('E26', 'event', 'Viral Fundraiser', 'The internet chips in for whoever is struggling most. The poorest player receives Rp800K.', '[["poorgift",800000]]'::jsonb, null),
  ('E27', 'event', 'Gotong Royong', 'Neighbors help neighbors. The richest player gives Rp600K to the poorest.', '[["richtax",600000]]'::jsonb, null),
  ('E28', 'event', 'Office Potluck', 'Everyone brings food, everyone gets a little bonus. Every player receives Rp100K.', '[["allcash",100000]]'::jsonb, null),
  ('E29', 'event', 'Food Poisoning', 'The night-market sate was suspicious. Pay Rp400K for medicine.', '[["pay",400000,"health"]]'::jsonb, null),
  ('E30', 'event', 'Lucky Lottery Ticket', 'A scratch card from the minimarket actually won.', '[["cash",400000]]'::jsonb, null),
  ('E31', 'event', 'Hospital Bill', 'A “quick check-up” turns into three nights and a long receipt.', '[["pay",1200000,"health"]]'::jsonb, null),
  ('E32', 'event', 'Laptop Stolen', 'You looked away from your café table for one sip.', '[["pay",800000]]'::jsonb, null),
  ('E33', 'event', 'Family Emergency', 'Your relatives back home need help. Family comes first.', '[["pay",500000]]'::jsonb, null),
  ('E34', 'event', '“Your Package Is Held”', 'A caller says customs is holding your parcel. Just one small transfer…', '[]'::jsonb, '[{"l":"Transfer the “fee”","fx":[["pay",400000]],"m":"There was no package."},{"l":"Hang up and block","fx":[["back",2]],"m":"You missed your bus while arguing."}]'::jsonb),
  ('E35', 'event', 'Kos Rent Goes Up', 'The landlord found new paint and a new price.', '[["pay",400000]]'::jsonb, null),
  ('E36', 'event', 'Pinjol Debt Collector', 'An old online loan you forgot about comes back with interest.', '[["pay",1000000]]'::jsonb, null),
  ('R01', 'reality', 'Wedding Invitation', 'An old classmate is getting married. You’re not close, but the envelope is mandatory.', '[]'::jsonb, '[{"l":"Thick envelope","fx":[["pay",400000]]},{"l":"Standard envelope","fx":[["pay",200000]]},{"l":"“I’m out of town”","fx":[["jam"]],"m":"Hiding at home turned into a three-day jam."}]'::jsonb),
  ('R02', 'reality', 'Independence Day Dues', 'The neighborhood committee arrives with a notebook and a hopeful smile.', '[["pay",50000]]'::jsonb, null),
  ('R03', 'reality', 'Vehicle Tax Due', 'Your registration reminds you the state has needs too.', '[["pay",400000]]'::jsonb, null),
  ('R04', 'reality', 'Fuel Price Hike', 'Petrol goes up. Everything else follows. Every player pays Rp500K to the Community Fund.', '[["allpay",500000]]'::jsonb, null),
  ('R05', 'reality', 'New Toll Road Opens', 'Everything is connected now. Advance to the nearest transport space; pay double rent if it’s owned.', '[["nearest"]]'::jsonb, null),
  ('R06', 'reality', 'Monsoon Floods', 'Streets became rivers. Every player pays Rp200K per house and Rp800K per tower they own.', '[["allrepairs",200000,800000]]'::jsonb, null),
  ('R07', 'reality', 'Building Inspection', 'An inspector finds your buildings need “adjustments”. Pay Rp300K per house and Rp1M per tower.', '[["repairs",300000,1000000]]'::jsonb, null),
  ('R08', 'reality', 'Police Checkpoint', 'Papers, please. Go to the Traffic Jam.', '[["jam"]]'::jsonb, null),
  ('R09', 'reality', 'Rush Hour Commute', 'Packed carriage, mystery aromas, feet not touching the floor.', '[["goto",16]]'::jsonb, null),
  ('R10', 'reality', 'Rupiah Slides', 'Imported things get pricier overnight. Every player pays Rp300K to the Community Fund.', '[["allpay",300000]]'::jsonb, null),
  ('R11', 'reality', 'Land Values Rise', 'A new mall is planned nearby. Collect Rp100K for each property you own.', '[["perprop",100000]]'::jsonb, null),
  ('R12', 'reality', 'Tax Refund', 'You overpaid last year. The money comes home.', '[["cash",200000]]'::jsonb, null),
  ('R13', 'reality', 'Car Free Day', 'A slow walk and a bag of cilok. Move back 3 spaces.', '[["back",3]]'::jsonb, null),
  ('R14', 'reality', 'Blackout', 'The power cut out right before your deadline. Advance to the Power Company.', '[["goto",9]]'::jsonb, null),
  ('R15', 'reality', 'Small Business Grant', 'Your side business gets a government grant.', '[["cash",300000]]'::jsonb, null),
  ('R16', 'reality', 'Long Weekend', 'Three holidays in a row. Advance to the Rest Area.', '[["goto",18]]'::jsonb, null),
  ('R17', 'reality', 'Mystery Parking Attendant', 'Invisible when you arrive, right there when you leave.', '[["pay",50000]]'::jsonb, null),
  ('R18', 'reality', 'Government Cash Aid', 'Direct cash assistance is disbursed. Every player receives Rp200K.', '[["allcash",200000]]'::jsonb, null),
  ('R19', 'reality', 'Collective Leave Day', 'A surprise cuti bersama. Every player gets Rp200K in holiday pay.', '[["allcash",200000,"bonus"]]'::jsonb, null),
  ('R20', 'reality', 'Bali Tourism Boom', 'Flights are full. Owners of Bali and Jakarta collect Rp300K per city; Tour Guides get Rp400K.', '[["regionbonus","navy",300000],["jobcash",["tourism"],400000]]'::jsonb, null),
  ('R21', 'reality', 'Nickel Boom', 'Smelters everywhere. Owners of Sulawesi cities collect Rp300K per city.', '[["regionbonus","pink",300000]]'::jsonb, null),
  ('R22', 'reality', 'New Capital Hype', 'Everyone wants land near the new capital. Owners of Kalimantan cities collect Rp300K per city.', '[["regionbonus","orange",300000]]'::jsonb, null),
  ('R23', 'reality', 'Coffee Export Boom', 'Indonesian beans are trending abroad. Coffee Farmers get Rp700K; Warung Owners get Rp200K.', '[["jobcash",["farm"],700000],["jobcash",["biz"],200000]]'::jsonb, null),
  ('R24', 'reality', 'Ojol Surge Pricing', 'It’s raining at 5 p.m. Ojol Drivers earn Rp500K; everyone else pays Rp50K for rides.', '[["jobcash",["gig"],500000],["jobpay",["gig"],50000]]'::jsonb, null),
  ('R25', 'reality', 'Civil Servant Pay Raise', 'Government salaries go up. Civil Servants and Teachers get Rp400K.', '[["jobcash",["gov"],400000]]'::jsonb, null),
  ('R26', 'reality', 'Tech Winter', 'Startups cut staff to “extend runway”. Startup Engineers lose Rp1M.', '[["jobcash",["tech"],-1000000,"layoff"]]'::jsonb, null),
  ('R27', 'reality', 'Algorithm Change', 'Reach drops 80% overnight. Content Creators lose Rp600K.', '[["jobcash",["creative"],-600000]]'::jsonb, null),
  ('R28', 'reality', 'El Niño Drought', 'The rains don’t come. Coffee Farmers lose Rp800K.', '[["jobcash",["farm"],-800000]]'::jsonb, null),
  ('R29', 'reality', 'Jakarta Floods', 'The capital is underwater again. Owners of Bali and Jakarta pay Rp600K per city.', '[["regionpay","navy",600000]]'::jsonb, null),
  ('R30', 'reality', 'Port Strike', 'Ships wait offshore. Every transport owner pays Rp400K per transport space.', '[["typepay","transport",400000]]'::jsonb, null),
  ('R31', 'reality', 'Interest Rate Hike', 'The central bank raises rates. Every player pays Rp200K per mortgaged property.', '[["mortpay",200000]]'::jsonb, null),
  ('R32', 'reality', 'Rice Price Spike', 'Nasi is life, and life got pricier. Every player pays Rp300K to the Community Fund.', '[["allpay",300000]]'::jsonb, null),
  ('R33', 'reality', 'Mass Layoffs', 'Corporate “efficiency”. Office workers (managers, bankers, lawyers, graduates) lose Rp800K.', '[["jobcash",["office"],-800000,"layoff"]]'::jsonb, null),
  ('R34', 'reality', 'National Shopping Day', 'Online Sellers earn Rp600K and Content Creators Rp300K. Everyone else spends Rp100K.', '[["jobcash",["seller"],600000],["jobcash",["creative"],300000],["jobpay",["seller","creative"],100000]]'::jsonb, null),
  ('R35', 'reality', 'Volcano Ash Cloud', 'Flights grounded across the islands. Tour Guides lose Rp600K; the Airport owner pays Rp500K.', '[["jobcash",["tourism"],-600000],["ownerpay",27,500000]]'::jsonb, null),
  ('R36', 'reality', 'Union Wage Deal', 'Factory unions win a raise. Factory Workers get Rp500K.', '[["jobcash",["union"],500000]]'::jsonb, null),
  ('R37', 'reality', 'Property Tax (PBB) Due', 'The tax office remembers every plot you own. Pay Rp300K per property.', '[["propfee",300000]]'::jsonb, null),
  ('R38', 'reality', 'VAT Goes Up', 'Everything costs a little more. Every player pays Rp200K per property they own.', '[["allpropfee",200000]]'::jsonb, null),
  ('R39', 'reality', 'Forest Fire Haze', 'Smoke covers the islands for weeks. Owners of Kalimantan and Sumatra cities pay Rp500K per city.', '[["regionpay","orange",500000],["regionpay","red",500000]]'::jsonb, null),
  ('R40', 'reality', 'Earthquake', 'The ground shakes in Nusa Tenggara and Sulawesi. Owners there pay Rp500K per city for repairs.', '[["regionpay","sky",500000],["regionpay","pink",500000]]'::jsonb, null),
  ('R41', 'reality', 'BPJS Premium Rises', 'Health insurance gets pricier. Every player pays Rp300K to the Community Fund.', '[["allpay",300000]]'::jsonb, null),
  ('R42', 'reality', 'Electricity Tariff Hike', 'The token runs out twice as fast. Pay Rp500K; the Power Company owner pays Rp300K too.', '[["pay",500000],["ownerpay",9,300000]]'::jsonb, null),
  ('R43', 'reality', 'Toll Fares Rise', 'Every gate costs more. Every player pays Rp200K to the Community Fund.', '[["allpay",200000]]'::jsonb, null),
  ('R44', 'reality', 'Market Crash', 'The stock index tumbles. The richest player loses Rp2M to the Community Fund.', '[["richpay",2000000]]'::jsonb, null);
insert into public.job_definitions (id, name, salary_m, pros, cons, data) values
  ('pns', 'Civil Servant', 14, array['Can’t be laid off', 'Card fines cost you half']::text[], array['Modest salary']::text[], '{"name":"Civil Servant","ic":"🗂️","sal":14,"safe":true,"cardNeg":-50,"tags":["gov"],"pros":["Can’t be laid off","Card fines cost you half"],"cons":["Modest salary"]}'::jsonb),
  ('startup', 'Startup Engineer', 18, array['High salary']::text[], array['Tech-layoff cards hit you', 'Living costs Rp400K each Payday']::text[], '{"name":"Startup Engineer","ic":"🚀","sal":18,"life":4,"tags":["tech"],"pros":["High salary"],"cons":["Tech-layoff cards hit you","Living costs Rp400K each Payday"]}'::jsonb),
  ('ojol', 'Ojol Driver', 13, array['Traffic Jam holds you 1 turn, no fee', 'Surge-pricing cards pay you']::text[], array['Low salary']::text[], '{"name":"Ojol Driver","ic":"🛵","sal":13,"quickJam":true,"tags":["gig"],"pros":["Traffic Jam holds you 1 turn, no fee","Surge-pricing cards pay you"],"cons":["Low salary"]}'::jsonb),
  ('creator', 'Content Creator', 11, array['Card income +50%', 'Salary can reach Rp2.7M']::text[], array['Salary can be Rp0', 'Algorithm cards hurt']::text[], '{"name":"Content Creator","ic":"🎥","sal":11,"var":[0,250],"cardPos":50,"tags":["creative"],"pros":["Card income +50%","Salary can reach Rp2.7M"],"cons":["Salary can be Rp0","Algorithm cards hurt"]}'::jsonb),
  ('seller', 'Online Seller', 10, array['+Rp100K per property you own each Payday', 'Shopping-day cards pay you']::text[], array['Low base salary']::text[], '{"name":"Online Seller","ic":"📦","sal":10,"perProp":1,"tags":["seller"],"pros":["+Rp100K per property you own each Payday","Shopping-day cards pay you"],"cons":["Low base salary"]}'::jsonb),
  ('agent', 'Property Agent', 12, array['Buy from the bank 10% cheaper']::text[], array['Pay 20% more rent (always out viewing)']::text[], '{"name":"Property Agent","ic":"🏘️","sal":12,"buy":10,"rentPay":20,"tags":["biz"],"pros":["Buy from the bank 10% cheaper"],"cons":["Pay 20% more rent (always out viewing)"]}'::jsonb),
  ('contractor', 'Contractor', 11, array['Houses and towers 25% cheaper']::text[], array['Repair and flood fines doubled']::text[], '{"name":"Contractor","ic":"👷","sal":11,"build":25,"repairs":100,"tags":["biz"],"pros":["Houses and towers 25% cheaper"],"cons":["Repair and flood fines doubled"]}'::jsonb),
  ('manager', 'Corporate Manager', 23, array['Top salary']::text[], array['Car loan: repay Rp2.5M at your first Payday', 'Mass-layoff cards hit you']::text[], '{"name":"Corporate Manager","ic":"👔","sal":23,"owe":25,"tags":["office"],"pros":["Top salary"],"cons":["Car loan: repay Rp2.5M at your first Payday","Mass-layoff cards hit you"]}'::jsonb),
  ('grad', 'Fresh Graduate', 8, array['Salary grows Rp200K every Payday', 'Parents chip in Rp1.5M at the start']::text[], array['Starts at only Rp800K']::text[], '{"name":"Fresh Graduate","ic":"🎓","sal":8,"grow":2,"start":15,"tags":["office"],"pros":["Salary grows Rp200K every Payday","Parents chip in Rp1.5M at the start"],"cons":["Starts at only Rp800K"]}'::jsonb),
  ('warung', 'Warung Owner', 11, array['+Rp500K whenever you land on a card space or the Night Market']::text[], array['Average salary']::text[], '{"name":"Warung Owner","ic":"🍛","sal":11,"cardSpace":5,"tags":["biz"],"pros":["+Rp500K whenever you land on a card space or the Night Market"],"cons":["Average salary"]}'::jsonb),
  ('doctor', 'Doctor', 19, array['High salary', 'Immune to illness cards']::text[], array['Living costs Rp400K each Payday']::text[], '{"name":"Doctor","ic":"🩺","sal":19,"life":4,"immune":["health"],"tags":["health"],"pros":["High salary","Immune to illness cards"],"cons":["Living costs Rp400K each Payday"]}'::jsonb),
  ('teacher', 'Teacher', 9, array['Private tutoring: collect Rp100K from every player each Payday']::text[], array['Low salary']::text[], '{"name":"Teacher","ic":"📚","sal":9,"tutor":1,"tags":["gov"],"pros":["Private tutoring: collect Rp100K from every player each Payday"],"cons":["Low salary"]}'::jsonb),
  ('guide', 'Tour Guide', 12, array['+75% rent on Bali, Labuan Bajo and transport', 'Tourism-boom cards pay you']::text[], array['Tourism-slump cards hurt']::text[], '{"name":"Tour Guide","ic":"🧭","sal":12,"tourism":75,"tags":["tourism"],"pros":["+75% rent on Bali, Labuan Bajo and transport","Tourism-boom cards pay you"],"cons":["Tourism-slump cards hurt"]}'::jsonb),
  ('banker', 'Banker', 16, array['Mortgages pay 60% and redeem without the 10% fee']::text[], array['Living costs Rp200K each Payday', 'Mass-layoff cards hit you']::text[], '{"name":"Banker","ic":"🏦","sal":16,"life":2,"mortgage":60,"tags":["office"],"pros":["Mortgages pay 60% and redeem without the 10% fee"],"cons":["Living costs Rp200K each Payday","Mass-layoff cards hit you"]}'::jsonb),
  ('lawyer', 'Lawyer', 17, array['Take over cities at 125% instead of 150%', 'Nobody can take over your cities']::text[], array['Living costs Rp300K each Payday']::text[], '{"name":"Lawyer","ic":"⚖️","sal":17,"life":3,"take":125,"protect":true,"tags":["office"],"pros":["Take over cities at 125% instead of 150%","Nobody can take over your cities"],"cons":["Living costs Rp300K each Payday"]}'::jsonb),
  ('factory', 'Factory Worker', 13, array['Union: can’t be laid off', 'Bonus cards pay you Rp300K extra']::text[], array['Average salary']::text[], '{"name":"Factory Worker","ic":"🏭","sal":13,"safe":true,"union":3,"tags":["union"],"pros":["Union: can’t be laid off","Bonus cards pay you Rp300K extra"],"cons":["Average salary"]}'::jsonb),
  ('farmer', 'Coffee Farmer', 9, array['Harvest pays 60–230% of Rp900K', 'Commodity-boom cards pay you']::text[], array['Drought cards hurt']::text[], '{"name":"Coffee Farmer","ic":"☕","sal":9,"var":[60,230],"tags":["farm"],"pros":["Harvest pays 60–230% of Rp900K","Commodity-boom cards pay you"],"cons":["Drought cards hurt"]}'::jsonb);
